CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_path text, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_own ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'admin' CHECK (role = 'admin'));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_own ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.cms_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.cms_is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cms_is_admin() TO authenticated;
CREATE FUNCTION public.cms_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', '')); RETURN NEW; END $$;
CREATE TRIGGER cms_signup_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.cms_create_profile();
CREATE TABLE public.blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_categories TO authenticated; GRANT SELECT ON public.blog_categories TO anon; GRANT ALL ON public.blog_categories TO service_role;
ALTER TABLE public.blog_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_public ON public.blog_categories FOR SELECT TO anon, authenticated USING (active);
CREATE POLICY categories_admin ON public.blog_categories FOR ALL TO authenticated USING (public.cms_is_admin()) WITH CHECK (public.cms_is_admin());
CREATE TABLE public.blog_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), translation_group uuid NOT NULL DEFAULT gen_random_uuid(), locale text NOT NULL DEFAULT 'de' CHECK (locale IN ('de','en','es')), title text NOT NULL DEFAULT '', slug text NOT NULL, content text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', cover_path text, cover_alt text NOT NULL DEFAULT '', author text NOT NULL DEFAULT '', show_author boolean NOT NULL DEFAULT true, show_updated boolean NOT NULL DEFAULT false, published_at timestamptz, original_published_at timestamptz, updated_at timestamptz, meta_title text NOT NULL DEFAULT '', meta_description text NOT NULL DEFAULT '', canonical_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','scheduled','published')), scheduled_at timestamptz, category_ids uuid[] NOT NULL DEFAULT '{}', published_snapshot jsonb, created_at timestamptz NOT NULL DEFAULT now(), modified_at timestamptz NOT NULL DEFAULT now(), UNIQUE(locale,slug), UNIQUE(translation_group,locale));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_posts TO authenticated; GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY posts_admin ON public.blog_posts FOR ALL TO authenticated USING (public.cms_is_admin()) WITH CHECK (public.cms_is_admin());
CREATE INDEX blog_public_time ON public.blog_posts(status,scheduled_at);
CREATE TABLE public.blog_post_categories (post_id uuid REFERENCES public.blog_posts(id) ON DELETE CASCADE, category_id uuid REFERENCES public.blog_categories(id) ON DELETE CASCADE, PRIMARY KEY(post_id,category_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_post_categories TO authenticated; GRANT ALL ON public.blog_post_categories TO service_role;
ALTER TABLE public.blog_post_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY links_admin ON public.blog_post_categories FOR ALL TO authenticated USING (public.cms_is_admin()) WITH CHECK (public.cms_is_admin());
CREATE TABLE public.blog_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.blog_posts(id) ON DELETE CASCADE, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.blog_revisions TO authenticated; GRANT ALL ON public.blog_revisions TO service_role;
ALTER TABLE public.blog_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY revisions_admin ON public.blog_revisions FOR SELECT TO authenticated USING (public.cms_is_admin());
CREATE TABLE public.blog_redirects (locale text NOT NULL, old_slug text NOT NULL, post_id uuid NOT NULL REFERENCES public.blog_posts(id) ON DELETE CASCADE, PRIMARY KEY(locale,old_slug));
GRANT SELECT ON public.blog_redirects TO authenticated; GRANT ALL ON public.blog_redirects TO service_role;
ALTER TABLE public.blog_redirects ENABLE ROW LEVEL SECURITY;
CREATE POLICY redirects_admin ON public.blog_redirects FOR SELECT TO authenticated USING (public.cms_is_admin());
CREATE TABLE public.blog_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text NOT NULL UNIQUE, alt text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_media TO authenticated; GRANT ALL ON public.blog_media TO service_role;
ALTER TABLE public.blog_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY media_admin ON public.blog_media FOR ALL TO authenticated USING (public.cms_is_admin()) WITH CHECK (public.cms_is_admin());
CREATE FUNCTION public.cms_before_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
NEW.modified_at := now();
IF TG_OP = 'UPDATE' THEN
NEW.original_published_at := OLD.original_published_at;
IF OLD.published_snapshot IS NOT NULL AND NEW.published_snapshot IS DISTINCT FROM OLD.published_snapshot THEN INSERT INTO public.blog_revisions(post_id,snapshot) VALUES (OLD.id, OLD.published_snapshot); END IF;
IF OLD.slug <> NEW.slug AND OLD.published_snapshot IS NOT NULL THEN INSERT INTO public.blog_redirects(locale,old_slug,post_id) VALUES (OLD.locale,OLD.slug,OLD.id) ON CONFLICT(locale,old_slug) DO UPDATE SET post_id=EXCLUDED.post_id; END IF;
END IF;
IF NEW.status IN ('published','scheduled') AND NEW.published_snapshot IS NOT NULL AND NEW.original_published_at IS NULL THEN NEW.original_published_at := COALESCE(NEW.published_at,NEW.scheduled_at,now()); END IF;
RETURN NEW; END $$;
CREATE TRIGGER cms_post_before BEFORE INSERT OR UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.cms_before_post();
CREATE FUNCTION public.cms_sync_categories() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN DELETE FROM public.blog_post_categories WHERE post_id=NEW.id; INSERT INTO public.blog_post_categories(post_id,category_id) SELECT NEW.id,c.id FROM public.blog_categories c WHERE c.id=ANY(NEW.category_ids); RETURN NEW; END $$;
CREATE TRIGGER cms_categories AFTER INSERT OR UPDATE OF category_ids ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.cms_sync_categories();
CREATE FUNCTION public.cms_public_posts(p_locale text DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.published_snapshot || jsonb_build_object('id',p.id,'slug',p.slug,'locale',p.locale,'translation_group',p.translation_group,'original_published_at',p.original_published_at) FROM public.blog_posts p WHERE p.published_snapshot IS NOT NULL AND (p.status='published' OR (p.status='scheduled' AND p.scheduled_at<=now())) AND (p_locale IS NULL OR p.locale=p_locale) $$;
REVOKE ALL ON FUNCTION public.cms_public_posts(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cms_public_posts(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.cms_public_redirect(p_locale text,p_slug text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.slug FROM public.blog_redirects r JOIN public.blog_posts p ON p.id=r.post_id WHERE r.locale=p_locale AND r.old_slug=p_slug AND p.slug<>p_slug AND p.published_snapshot IS NOT NULL AND (p.status='published' OR (p.status='scheduled' AND p.scheduled_at<=now())) $$;
REVOKE ALL ON FUNCTION public.cms_public_redirect(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cms_public_redirect(text,text) TO anon,authenticated;
CREATE FUNCTION public.cms_public_media(p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.blog_posts p WHERE p.published_snapshot IS NOT NULL AND (p.status='published' OR (p.status='scheduled' AND p.scheduled_at<=now())) AND (p.published_snapshot->>'cover_path'=p_path OR position('/api/public/blog-media?path=' || p_path IN p.published_snapshot->>'content')>0)) $$;
REVOKE ALL ON FUNCTION public.cms_public_media(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cms_public_media(text) TO anon,authenticated;
CREATE POLICY storage_blog_admin ON storage.objects FOR ALL TO authenticated USING (bucket_id='blog-media' AND public.cms_is_admin()) WITH CHECK (bucket_id='blog-media' AND public.cms_is_admin());